import json
with open('/app/resources/treasury_bulletin_1990_06.json', 'r') as f:
    data = json.load(f)

# Look for any table around page 113 area
def find_exchange_stuff(obj, path='', depth=0):
    if depth > 10:
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if 'exchange' in str(k).lower() or 'esf' in str(k).lower() or 'stabilization' in str(k).lower():
                print(f'Found: {new_path}')
            find_exchange_stuff(v, new_path, depth+1)
    elif isinstance(obj, list) and len(obj) < 20:
        for i, item in enumerate(obj):
            find_exchange_stuff(item, f'{path}[{i}]', depth+1)

find_exchange_stuff(data)
